#![allow(unused)]
use verus::prelude::*;

// We assert that the input vector is nonempty (so indexing at 0 is safe),
// we guarantee that the output has the same length,
// that every index past 0 is unchanged,
// and that the 0th character becomes 'A' exactly when the original was
// an ASCII‐lowercase letter, otherwise it stays the same.
#[verus::external_body]
#[requires(word.len() >= 1)]
#[ensures(result.len() == word.len())]
#[ensures(
    forall |i: usize| 0 < i && i < word.len() 
        ==> result[i] == word[i]
)]
#[ensures(
    if word[0].is_ascii_lowercase() {
        result[0] == 'A'
    } else {
        result[0] == word[0]
    }
)]
fn capitalize_first_letter(mut word: Vec<char>) -> Vec<char> {
    // If the first character is a lowercase ASCII letter, replace it with 'A'.
    if word[0].is_ascii_lowercase() {
        word[0] = 'A';
    }
    // Otherwise (it is already uppercase), we leave it unchanged.
    word
}

fn main() {
    let examples = vec![
        vec!['h', 'e', 'l', 'l', 'o'],
        vec!['A', 'b', 'c'],
        vec!['z', 'Z'],
        vec!['M', 'o', 'r', 'n', 'i', 'n', 'g'],
    ];

    for word in examples {
        let result = capitalize_first_letter(word.clone());
        println!("input: {:?} -> output: {:?}", word, result);
    }
}